def transform(grid):
    n = len(grid[0])
    seed = next(c for c, value in enumerate(grid[0]) if value == 2)
    out = []
    for r in range(n):
        row = [0] * n
        for c in range(n):
            distance = abs(c - seed)
            if distance == r:
                row[c] = 2
            elif distance < r and (c - r - seed) % 4 == 0:
                row[c] = 1
        out.append(row)
    return out
